def main():
    sourcepath=RUN/'current_sources.jsonl';sources={}
    for lineno,line in enumerate(sourcepath.read_bytes().splitlines(),1):
        r=json.loads(line)
        if r.get('split')!='train':continue
        if any(t in r['sample_id'].lower() for t in ['holdout','eval','pilot','protected']):continue
        sources[r['sample_id']]=(r,line,lineno)
    g4path=RUN/'g4_audit/page_review.jsonl';g4=[json.loads(x) for x in g4path.read_text(encoding='utf-8').splitlines()]
    allc={c for r in g4 for c in r['gap_candidates']}
    assert allc==set(D)|set(NUMERIC_ALREADY_HANDLED),(allc-set(D)-set(NUMERIC_ALREADY_HANDLED),set(D)-allc)
    fields=['problem','givens','requested_quantity','student_work','initial_guidance','hints','worked_steps','expected_answer']
    records=[];used=set()
    for cid,(status,aliases,reason,merges) in D.items():
        nearest=[]
        for alias in aliases:
            sid=ALIASES[alias];r,line,n=sources[sid];used.add(sid)
            nearest.append(dict(sample_id=sid,grade=r['grade'],source_line_number=n,source_row_sha256=hashlib.sha256(line).hexdigest(),semantic_fields_read=fields))
        loc=[dict(book_id=r['book_id'],printed_page=r['printed_page'],image_url=r['image_url'],image_sha256=r['image_sha256'],exercise_types_read=r['exercise_types_read'],receipt_origin='ROOT_ACTUAL_VISUAL_PAGE_READ') for r in g4 if cid in r['gap_candidates']]
        records.append(dict(candidate_id=cid,status=status,nearest_actual_valid_train_rows=nearest,actual_page_receipts=loc,semantic_adjudication=reason,merge_targets=merges.split('; ') if merges else [],pending_confirmed_gap_scope='Confirmed relation/representation difference against these actual nearest rows; not exhaustive absence proof over the whole archive.' if status=='PENDING_CONFIRMED_GAP' else '',asset_or_physical_completeness_claimed=False,authoring_performed=False))
    # Cross-grade records are references, not fresh claims of having viewed their images.
    crossfiles=['g1v2_audit/candidate_adjudication.json','g2v1_audit/page_review.jsonl','g2v2_audit/page_review.jsonl','g3_audit/candidate_adjudication.json','g3_spatial_append/peer_review.json']
    cross=[]
    for f in crossfiles:
        q=RUN/f
        if q.exists():cross.append(dict(path=f,sha256=hashlib.sha256(q.read_bytes()).hexdigest(),basis='PREEXISTING_ACTUAL_PAGE_RECEIPT_OR_CONTENT_REVIEW; G2 standalone adjudication files not present at this checkpoint'))
    counts={s:sum(r['status']==s for r in records) for s in ['COVERED','MERGED','PENDING_CONFIRMED_GAP']}
    out=dict(scope='Finite preexisting G4 page candidate labels only. No authoring, no Drive mutation, no training.',all_original_candidate_label_count=len(allc),numeric_already_handled_count=len(NUMERIC_ALREADY_HANDLED),numeric_already_handled=NUMERIC_ALREADY_HANDLED,remaining_candidate_count=len(records),status_counts=counts,source_file_sha256=hashlib.sha256(sourcepath.read_bytes()).hexdigest(),source_row_hash_basis='Exact UTF-8 JSONL source line bytes excluding line terminator',g4_page_receipt_sha256=hashlib.sha256(g4path.read_bytes()).hexdigest(),reviewer='resume_g1_page_audit',cross_grade_evidence=cross,valid_train_only=True,protected_eval_pilot_used=False,semantic_comparison_limit='Nearest rows were actually read through problem/givens/request/student_work/steps/reasons/explanations/answers/initial guidance/all hints; retrieving or not finding keywords is not semantic proof. MERGED can target a still-pending queue, not accepted coverage. COVERED refers to the explicit math relation, not unseen visual or physical outcomes.',candidates=records,nearest_full_field_evidence=[dict(sample_id=sid,source_line_number=sources[sid][2],source_row_sha256=hashlib.sha256(sources[sid][1]).hexdigest(),grade=sources[sid][0]['grade'],split='train',semantic_field_values={k:sources[sid][0].get(k) for k in fields}) for sid in sorted(used)])
    path=RUN/'g4_audit/remaining_candidate_adjudication.json';path.write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(json.dumps(dict(original_candidates=len(allc),remaining=len(records),nearest_full_field_rows=len(used),status_counts=counts,sha256=hashlib.sha256(path.read_bytes()).hexdigest())))

if __name__=='__main__':main()
